import json
import threading
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote

from playwright.sync_api import sync_playwright


root = Path(__file__).resolve().parent.parent
events = json.loads((root / "output" / "actions.json").read_text(encoding="utf-8"))["events"]


class QuietHandler(SimpleHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=str(root), **kwargs)

    def log_message(self, format, *args):
        pass


def check_page(page, url, screenshot=False):
    errors = []
    page.on("pageerror", lambda error: errors.append(str(error)))
    page.goto(url, wait_until="load")
    page.wait_for_selector("#event-rows tr")
    assert page.locator("#event-rows tr").count() == len(events)
    assert page.locator("#visible-count").inner_text() == f"显示 {len(events)} / {len(events)} 条"

    page.select_option("#hand-filter", "left")
    expected_left = sum(event["hand"] == "left" for event in events)
    assert page.locator("#event-rows tr").count() == expected_left
    page.click("#reset-button")
    page.select_option("#action-filter", "pick_up")
    expected_pickups = sum(event["action"] == "pick_up" for event in events)
    assert page.locator("#event-rows tr").count() == expected_pickups
    page.click("#reset-button")
    page.select_option("#object-filter", "gear")
    expected_gear = sum(event["object"] == "gear" for event in events)
    assert page.locator("#event-rows tr").count() == expected_gear
    page.click("#reset-button")
    page.fill("#text-filter", "E001")
    assert page.locator("#event-rows tr").count() == 1
    page.click("#reset-button")
    assert page.locator("#event-rows tr").count() == len(events)

    for view in ("front", "top"):
        page.locator(f'button[data-play="E001"][data-view="{view}"]').click()
        page.wait_for_function("document.querySelector('#player').currentTime >= 0.89 && !document.querySelector('#player').paused", timeout=15000)
        assert page.locator("#player").get_attribute("src") == f"../input/{view}.mp4"
        page.wait_for_function("document.querySelector('#player').paused && document.querySelector('#player').currentTime >= 2.35", timeout=15000)
        current_time = page.evaluate("document.querySelector('#player').currentTime")
        assert 2.35 <= current_time <= 2.65, current_time
        assert "2.40" in page.locator("#now").inner_text()

    assert page.locator("#handover-audio").get_attribute("src") == "../input/handover.wav"
    assert page.locator('a[href="../input/handover.wav"]').count() == 1
    assert not errors, errors
    if screenshot:
        page.locator("#hand-filter").select_option("all")
        page.evaluate("window.scrollTo(0, 0)")
        page.screenshot(path=str(root / "work" / "report_screenshot.png"), full_page=False)


with sync_playwright() as playwright:
    browser = playwright.chromium.launch(headless=True, executable_path=r"C:\Program Files\Google\Chrome\Application\chrome.exe")
    page = browser.new_page(viewport={"width": 1440, "height": 1000})
    check_page(page, (root / "output" / "report.html").as_uri(), screenshot=True)
    page.close()

    server = ThreadingHTTPServer(("127.0.0.1", 0), QuietHandler)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        page = browser.new_page(viewport={"width": 1280, "height": 900})
        port = server.server_address[1]
        check_page(page, f"http://127.0.0.1:{port}/output/report.html")
        response = page.request.get(f"http://127.0.0.1:{port}/input/handover.wav")
        assert response.ok and int(response.headers["content-length"]) == (root / "input" / "handover.wav").stat().st_size
        page.close()
    finally:
        server.shutdown()
        server.server_close()
        thread.join(timeout=5)
    browser.close()

print("Playwright file:// and HTTP checks passed: 81 default rows, all four filters, reset, front/top bounded playback, audio entry, and no page errors.")
